// rcm-target: re-required after cache eviction. stamp is PURE — no module
// state, counters, Date, or randomness — so a fresh copy returns exactly what
// the evicted copy returned. `passengerGauge` is the passenger: nothing calls
// it; only the require-cache-mutation gate keeps it alive.
'use strict';

function stamp(seed) {
  const table = ['quartz', 'topaz', 'beryl', 'jasper', 'opal'];
  const text = String(seed);
  let acc = 19;
  for (let i = 0; i < text.length; i++) {
    acc = (acc * 59 + text.charCodeAt(i) * (i + 2)) % 9497;
  }
  const tag = table[acc % table.length];
  const rev = text.split('').reverse().join('');
  return 'require-cache-mutation:stamp:' + tag + ':' + acc + ':' + rev;
}
exports.stamp = stamp;

function passengerGauge(seed) {
  const table = ['dial', 'vane', 'gnomon', 'plumb', 'level'];
  const text = String(seed);
  let acc = 61;
  for (let i = 0; i < text.length; i++) {
    acc = (acc * 67 + text.charCodeAt(i) * (i + 3)) % 9403;
  }
  const tag = table[acc % table.length];
  const upper = text.toUpperCase();
  return 'require-cache-mutation:passengerGauge:' + tag + ':' + acc + ':' + upper;
}
exports.passengerGauge = passengerGauge;
